const { byName, request, setText } = globalThis.SOAR;
const { autoLayout, createCanvas, frame } = globalThis.SOAR;
const { createHistory, emptyModel, fromDefinition } = globalThis.SOAR;

return (async () => {
const params = new URLSearchParams(location.search);
const playbookId = params.get("id");
const versionId = params.get("version");

const palette = await request("GET", "/api/playbooks/palette");

let version = null;
if (versionId) {
  version = await request("GET", `/api/playbooks/versions/${versionId}`);
} else if (playbookId) {
  const versions = await request("GET", `/api/playbooks/${playbookId}/versions`);
  version = versions.items?.find((v) => v.state === "draft") || versions.items?.[0];
}

const model = version ? fromDefinition(version.definition) : emptyModel();
if (version && !model.nodes.some((n) => n.editorPositioned !== false && n.x)) {
  autoLayout(model);
}

const state = {
  playbookId, versionId: version?.id, version, palette, model,
  history: createHistory(),
  selection: [],
  problems: [],
  dirty: false,
};
editorState = state;

state.canvas = createCanvas(byName("editorCanvas"), {
  onSelect: (ids) => { state.selection = ids; refresh({ silent: true }); },
  onChange: (options) => {
    if (!options?.silent) markDirty(options?.label || "edit");
    refresh({ silent: true });
  },
  onConnect: (from, port, to) => connectNodes(from, port, to),
  onDelete: (ids) => deleteNodes(ids),
  onDuplicate: (ids) => duplicateNodes(ids),
  onUndo: () => editorUndo(),
  onRedo: () => editorRedo(),
  onSave: () => editorSave(),
  onFrame: () => frame(state.canvas),
  onDropPaletteItem: (item, at) => addFromPalette(item, at),
  onDropOnEmpty: (from, port, at) => {
    setText("statusMessage",
      "drop a node from the palette here, then drag the port onto it");
  },
  onOpen: (id) => { state.selection = [id]; refresh({ silent: true }); },
});

renderPalette(state);
setText("playbookName", version?.playbook_name || "New playbook");
const stateChip = byName("playbookState");
if (stateChip) {
  stateChip.textContent = `${(version?.state || "draft").toUpperCase()}` +
                          `${version?.version ? " v" + version.version : ""}`;
  stateChip.dataset.state = version?.state || "draft";
}

refresh();
frame(state.canvas);
return state;
})();

const { byName, setText } = globalThis.SOAR;
const { renderCanvas } = globalThis.SOAR;
const { renderInspector } = globalThis.SOAR;
const { localValidate } = globalThis.SOAR;

const state = editorState;
if (!state) return;

state.problems = localValidate(state.model, state.palette);
renderCanvas(state.canvas, state.model, state.palette, state.problems);

const selected = state.model.nodes.find((n) => n.id === state.selection[0]);
renderInspector(byName("inspector"), selected, state.palette, {
  model: state.model,
  variables: state.palette.variables,
  update: (id, mutate) => {
    const node = state.model.nodes.find((n) => n.id === id);
    if (!node) return;
    state.history.push(state.model, "edit " + id);
    mutate(node);
    markDirty("edit " + id);
    refresh({ silent: true });
  },
  addCompensation: (id, commandKey) => addCompensation(id, commandKey),
});

renderProblems(state);
setText("dirtyFlag", state.dirty ? "unsaved changes" : "");

const { byName } = globalThis.SOAR;

const host = byName("paletteList");
if (!host) return;
host.replaceChildren();

const ORDER = ["Endpoint Response", "Identity Response", "Email & Phishing",
               "Network Blocking", "SIEM & Hunting", "Threat Intelligence",
               "Ticketing", "Notification", "Other"];

const sections = [
  ["Flow & Logic", (state.palette.core || []).filter(
     (n) => ["Flow", "Logic", "Control", "Data"].includes(n.group))],
  ["Actions", (state.palette.core || []).filter(
     (n) => ["Action", "AI"].includes(n.group))],
  ["Response (any EDR)", state.palette.response_actions || []],
];
for (const group of ORDER) {
  const entries = state.palette.commands?.[group];
  if (entries?.length) sections.push([group, entries]);
}

for (const [name, entries] of sections) {
  if (!entries?.length) continue;

  const heading = document.createElement("span");
  heading.className = "pb-group-name";
  heading.textContent = `${name} (${entries.length})`;
  host.append(heading);

  for (const entry of entries) {
    host.append(paletteItem(entry));
  }
}

const item = document.createElement("div");
item.className = "pb-item";
item.draggable = entry.available !== false;
item.dataset.available = String(entry.available !== false);
item.dataset.search = `${entry.label} ${entry.command || entry.action || entry.kind} ` +
                      `${entry.vendor || ""} ${entry.group || ""}`.toLowerCase();

const icon = document.createElement("span");
icon.className = "pb-item-icon";
icon.textContent = entry.icon || "\u25cb";

const label = document.createElement("span");
label.className = "pb-item-label";
label.textContent = entry.label;

item.append(icon, label);

if (entry.risk_level && entry.risk_level !== "low") {
  const risk = document.createElement("span");
  risk.className = "pb-item-risk";
  risk.dataset.risk = entry.risk_level;
  risk.textContent = entry.risk_level === "high" ? "HIGH" : "MED";
  item.append(risk);
}

const tooltip = [entry.doc, entry.warn, entry.unavailable_reason]
  .filter(Boolean).join("\n\n");
if (tooltip) item.title = tooltip;

item.addEventListener("dragstart", (event) => {
  event.dataTransfer.setData("application/x-soar-node", JSON.stringify(entry));
  event.dataTransfer.effectAllowed = "copy";
});
return item;

const query = (event?.currentTarget?.value || "").trim().toLowerCase();
for (const item of document.querySelectorAll(".pb-item[data-search]")) {
  item.hidden = Boolean(query) && !item.dataset.search.includes(query);
}
for (const heading of document.querySelectorAll(".pb-group-name")) {
  let sibling = heading.nextElementSibling;
  let visible = false;
  while (sibling && !sibling.classList.contains("pb-group-name")) {
    if (!sibling.hidden) visible = true;
    sibling = sibling.nextElementSibling;
  }
  heading.hidden = Boolean(query) && !visible;
}

const { newNodeId } = globalThis.SOAR;

const state = editorState;
state.history.push(state.model, `add ${entry.label}`);

const config = {};
const schema = entry.config_schema?.properties || entry.config_schema || {};
for (const [key, spec] of Object.entries(schema)) {
  if (spec?.default !== undefined) config[key] = spec.default;
}

const node = {
  id: newNodeId(entry.command || entry.action || entry.kind),
  kind: entry.kind,
  x: Math.round(at.x / 20) * 20,
  y: Math.round(at.y / 20) * 20,
  label: entry.label,
  command: entry.command,
  action: entry.action,
  config,
  settings: {},
};

state.model.nodes.push(node);
state.selection = [node.id];
state.canvas.selection = new Set([node.id]);
markDirty(`add ${entry.label}`);
refresh();

const state = editorState;
const MULTI = new Set(["branches", "case", "then"]);

state.history.push(state.model, "connect");
if (!MULTI.has(port)) {
  state.model.edges = state.model.edges.filter(
    (edge) => !(edge.from === from && edge.port === port));
}
if (state.model.edges.some((e) => e.from === from && e.port === port && e.to === to)) {
  return;
}

state.model.edges.push({ id: `e_${from}_${port}_${to}`, from, port, to });
markDirty("connect");
refresh();

const { setText } = globalThis.SOAR;

const state = editorState;
const removable = ids.filter((id) => {
  const node = state.model.nodes.find((n) => n.id === id);
  return node && node.kind !== "start";
});
if (!removable.length) {
  setText("statusMessage", "the Start node cannot be deleted");
  return;
}

state.history.push(state.model, `delete ${removable.length} node(s)`);
const gone = new Set(removable);
state.model.nodes = state.model.nodes.filter((n) => !gone.has(n.id));
state.model.edges = state.model.edges.filter(
  (e) => !gone.has(e.from) && !gone.has(e.to));
state.selection = [];
state.canvas.selection.clear();
markDirty("delete");
refresh();

const { newNodeId } = globalThis.SOAR;

const state = editorState;
state.history.push(state.model, "duplicate");
const copies = [];
for (const id of ids) {
  const node = state.model.nodes.find((n) => n.id === id);
  if (!node || node.kind === "start") continue;
  const copy = structuredClone(node);
  copy.id = newNodeId(node.command || node.action || node.kind);
  copy.x += 40;
  copy.y += 40;
  copies.push(copy);
}
state.model.nodes.push(...copies);
state.selection = copies.map((c) => c.id);
state.canvas.selection = new Set(state.selection);
markDirty("duplicate");
refresh();

const { setText } = globalThis.SOAR;
const { newNodeId } = globalThis.SOAR;

const state = editorState;
let entry = null;
for (const entries of Object.values(state.palette.commands || {})) {
  entry = entries.find((e) => e.command === commandKey) || entry;
}
if (!entry) {
  setText("statusMessage", `${commandKey} is not available in this organisation`);
  return;
}

const source = state.model.nodes.find((n) => n.id === nodeId);
state.history.push(state.model, "add compensation");

const node = {
  id: newNodeId(commandKey),
  kind: "command",
  command: commandKey,
  label: entry.label,
  x: (source?.x ?? 0),
  y: (source?.y ?? 0) + 200,
  // The undo takes the same target as the action it reverses.
  config: structuredClone(source?.config || {}),
  settings: {},
};
state.model.nodes.push(node);
if (source) source.compensation = node.id;
markDirty("add compensation");
refresh();

const { byName } = globalThis.SOAR;

const host = byName("problemList");
if (!host) return;
host.replaceChildren();

if (!state.problems.length) {
  const ok = document.createElement("div");
  ok.className = "pb-hint";
  ok.textContent = "No problems found in the browser. Publish re-runs the " +
    "full server-side validation, which also checks command schemas and " +
    "sub-playbook cycles.";
  host.append(ok);
  return;
}

const RANK = { error: 0, warning: 1, info: 2 };
for (const problem of [...state.problems].sort(
       (a, b) => RANK[a.severity] - RANK[b.severity])) {
  const row = document.createElement("div");
  row.className = "pb-problem";
  row.dataset.severity = problem.severity;
  row.textContent = problem.node ? `${problem.node}: ${problem.message}`
                                 : problem.message;
  if (problem.node) {
    row.addEventListener("click", () => {
      state.selection = [problem.node];
      state.canvas.selection = new Set([problem.node]);
      refresh({ silent: true });
    });
  }
  host.append(row);
}

const state = editorState;
if (!state) return;
state.dirty = true;
state.lastChange = label;
if (!state.unloadGuard) {
  state.unloadGuard = (event) => {
    if (!editorState?.dirty) return;
    event.preventDefault();
    event.returnValue = "";
  };
  window.addEventListener("beforeunload", state.unloadGuard);
}

const { setText } = globalThis.SOAR;

const state = editorState;
const entry = state.history.undo(state.model);
if (!entry) { setText("statusMessage", "nothing to undo"); return; }
state.model = entry.model;
state.canvas.selection.clear();
state.selection = [];
setText("statusMessage", `undid ${entry.label}`);
refresh({ silent: true });

const { setText } = globalThis.SOAR;

const state = editorState;
const entry = state.history.redo(state.model);
if (!entry) { setText("statusMessage", "nothing to redo"); return; }
state.model = entry.model;
setText("statusMessage", `redid ${entry.label}`);
refresh({ silent: true });

const { autoLayout, frame } = globalThis.SOAR;

const state = editorState;
state.history.push(state.model, "auto-layout");
autoLayout(state.model);
markDirty("auto-layout");
refresh();
frame(state.canvas);

const { request, setText } = globalThis.SOAR;
const { toDefinition } = globalThis.SOAR;

return (async () => {
const state = editorState;
const blocking = state.problems.filter((p) => p.severity === "error");
if (blocking.length) {
  // Saving a draft with errors is allowed - work in progress is normal.
  setText("statusMessage",
    `saving draft with ${blocking.length} unresolved error(s)`);
}

try {
  const saved = await request("POST", `/api/playbooks/${state.playbookId}/versions`, {
    definition: toDefinition(state.model),
    base_version_id: state.versionId,
  });
  state.versionId = saved.id;
  state.dirty = false;
  setText("dirtyFlag", "");
  setText("statusMessage", `saved draft v${saved.version}`);
  return saved;
} catch (error) {
  setText("statusMessage", `save failed: ${error.message}`);
  return null;
}
})();

const { request, setText } = globalThis.SOAR;
const { renderCanvas } = globalThis.SOAR;

return (async () => {
const state = editorState;
if (state.dirty) await editorSave();
if (!state.versionId) { setText("statusMessage", "save a draft first"); return; }

try {
  const result = await request("POST",
    `/api/playbooks/versions/${state.versionId}/validate`);
  state.problems = [
    ...localValidate(state.model, state.palette),
    ...(result.problems || []).map((message) => ({
      severity: "error", message, node: nodeFromMessage(message),
    })),
  ];
  renderCanvas(state.canvas, state.model, state.palette, state.problems);
  renderProblems(state);
  setText("statusMessage", result.problems?.length
    ? `${result.problems.length} problem(s) - see the inspector`
    : "validation clean");
} catch (error) {
  setText("statusMessage", `validate failed: ${error.message}`);
}
})();

const { request, setText } = globalThis.SOAR;

return (async () => {
const state = editorState;
if (state.dirty) await editorSave();
try {
  const run = await request("POST", `/api/playbooks/${state.playbookId}/dry-run`, {
    version_id: state.versionId,
  });
  window.open(`/execution.html?id=${encodeURIComponent(run.execution_id)}`, "_blank");
} catch (error) {
  setText("statusMessage", `dry run failed: ${error.message}`);
}
})();

const { request, setText } = globalThis.SOAR;

return (async () => {
const state = editorState;
if (state.dirty) await editorSave();
if (!state.versionId) { setText("statusMessage", "save a draft first"); return; }

try {
  const result = await request("POST",
    `/api/playbooks/versions/${state.versionId}/simulate`);
  setText("statusMessage", result.passed
    ? `simulation passed (${result.assertions} assertions)`
    : `simulation FAILED: ${result.failures?.join("; ")}`);
  if (result.execution_id) {
    window.open(`/execution.html?id=${encodeURIComponent(result.execution_id)}`,
                "_blank");
  }
} catch (error) {
  setText("statusMessage", `simulate failed: ${error.message}`);
}
})();

const { byName, request, setText } = globalThis.SOAR;
const { paletteEntry } = globalThis.SOAR;

return (async () => {
const state = editorState;
if (state.dirty) await editorSave();
if (!state.versionId) { setText("statusMessage", "save a draft first"); return; }

const mutating = state.model.nodes
  .map((node) => [node, paletteEntry(node, state.palette)])
  .filter(([, entry]) => entry?.effect === "mutating");

const summary = mutating.length
  ? "This playbook can change the estate:\n\n" + mutating
      .map(([node, entry]) => `  \u2022 ${entry.label} (${entry.risk_level})`)
      .join("\n") +
    "\n\nOnce published it can be started by a trigger. Continue?"
  : "Publish this playbook?";

if (!window.confirm(summary)) return;

try {
  await request("POST", `/api/playbooks/versions/${state.versionId}/publish`);
  setText("statusMessage", "published");
  const chip = byName("playbookState");
  if (chip) { chip.textContent = "PUBLISHED"; chip.dataset.state = "published"; }
} catch (error) {
  // Refusals here are the four publish gates: permission, legal transition,
  // clean validation, passing simulation. The message says which one.
  setText("statusMessage", `publish refused: ${error.message}`);
}
})();

const { bindDeclaredHandlers } = globalThis.SOAR;
bindDeclaredHandlers({
  onEditorDryRun,
  onEditorLayout,
  onEditorPublish,
  onEditorRedo,
  onEditorSave,
  onEditorSimulate,
  onEditorUndo,
  onEditorValidate,
  onPaletteSearch,
});
